def qiter(c: complex, n: int) -> complex:
    z = 0
    for _ in range(n):
        z = z**2 + c
    return z

def arithmetic_mandelbrot_set(p: int) -> dict:
    result = {}
    for c in range(p):
        z, period = 0, 0
        for n in range(1, p*p+2):
            z = (z*z + c) % p
            if z == 0:
                period = n
                break
        if period > 0:
            result[c] = period
    return result

def mandelbrot_poly_coeffs(n: int) -> list:
    if n == 0: return [0]
    poly = [0, 1]
    for _ in range(n - 1):
        deg = len(poly) - 1
        sq = [0] * (2*deg + 1)
        for i in range(deg+1):
            for j in range(deg+1):
                sq[i+j] += poly[i] * poly[j]
        while len(sq) < 2: sq.append(0)
        sq[1] += 1
        poly = sq
    return poly

